package org.beyondlight;

import java.time.Instant;
import java.util.*;

/** Connects open-data search, numeric screening, model exploration, and archival outcomes. */
public final class ResearchCycle {
 private ResearchCycle(){}
 public static List<Map<String,Object>> run(String query,DataRepository repository,List<EquationRegistry.Equation> equations,MachineDesign machine){
  List<Map<String,Object>> records=new ArrayList<>(),imports=new ArrayList<>(),downloadFailures=new ArrayList<>();
  List<Map<String,Object>> found;
  try{found=OpenDataClient.search(query);}catch(Exception e){return List.of(failure(query,"OPEN_DATA_SEARCH_FAILED",e.getMessage()));}
  for(Map<String,Object> record:found){if(imports.size()>=3)break;Object fo=record.get("files");if(!(fo instanceof List<?> files))continue;for(Object f:files){Map<String,Object> file=Json.map(f);String name=Objects.toString(file.get("name"),"");try{Map<String,Object> imported=OpenDataClient.downloadAndImport(Objects.toString(record.get("recordId"),""),name,repository);imports.add(imported);break;}catch(Exception e){Map<String,Object> bad=new LinkedHashMap<>();bad.put("recordId",record.get("recordId"));bad.put("title",record.get("title"));bad.put("filename",name);bad.put("reason",Objects.toString(e.getMessage(),"download/import failed"));downloadFailures.add(bad);}}}
  List<Map<String,Object>> attempts=discoverImportedOnly(repository,imports);
  records.addAll(attempts);List<Map<String,Object>> derivations=deriveEquations(equations);MachineDesign.Assembly assembly=machine.assemble();Map<String,Object> engineering=new LinkedHashMap<>();engineering.put("status",assembly.components()==0?"NO_COMPONENTS_TO_ASSESS":"PRELIMINARY_COMPONENT_AGGREGATE_ONLY");engineering.put("componentCount",assembly.components());engineering.put("massKg",assembly.massKg());engineering.put("powerW",assembly.powerW());engineering.put("energyJ",assembly.energyJ());engineering.put("heatW",assembly.heatW());engineering.put("missing",assembly.missing());engineering.put("dependencyErrors",assembly.dependencyErrors());engineering.put("classification",assembly.classification());engineering.put("limitations",List.of("Siklus belum menghasilkan desain mesin dari pola dataset.","Agregat komponen bukan analisis lengkap struktur, panas, kontrol, manufaktur, atau pengujian prototipe."));
  Map<String,Object> summary=new LinkedHashMap<>();summary.put("id",UUID.randomUUID().toString());summary.put("date",Instant.now().toString());summary.put("recordType","AUTOMATED_RESEARCH_CYCLE");summary.put("category","research");summary.put("title","Siklus riset otomatis: "+query);summary.put("model","Open-data search → numeric CSV validation → model exploration → internal cross-validation");summary.put("inputs",Map.of("query",query,"openRecordsFound",found.size(),"downloadLimit",3,"datasetsImported",imports.size()));summary.put("searchResults",found.stream().limit(10).map(r->Map.of("title",Objects.toString(r.get("title"),""),"url",Objects.toString(r.get("recordUrl"),""),"doi",Objects.toString(r.get("doi"),""))).toList());summary.put("sources",imports.stream().map(i->Json.map(i.get("source"))).toList());summary.put("downloads",imports);summary.put("failedDownloads",downloadFailures);summary.put("algebraicDerivations",derivations);summary.put("engineeringAssessment",engineering);long supported=attempts.stream().filter(a->("PATTERN_SUPPORTED_WITHIN_DATASET".equals(a.get("internalStatus"))||"UNVERIFIED_DATA_DERIVED_MODEL_CANDIDATE".equals(a.get("internalStatus")))).count();long replicated=attempts.stream().filter(a->("PREDICTION_REPLICATED_ON_SECOND_SOURCE_DATASET".equals(a.get("status"))||"MODEL_PREDICTION_REPLICATED_ON_SECOND_SOURCE_DATASET".equals(a.get("status")))).count();long failedRuns=attempts.stream().filter(a->"FAILED_EXPLORATORY_ATTEMPT".equals(a.get("status"))).count();summary.put("result",Map.of("status",attempts.isEmpty()&&imports.isEmpty()?found.isEmpty()?"NO_OPEN_RECORDS_FOUND":"NO_NUMERIC_CSV_IMPORTED":"RESEARCH_CYCLE_COMPLETED","patternCandidatesOutperformingBaselineInternally",supported,"autonomousModelSearches",attempts.stream().filter(a->"AUTONOMOUS_MODEL_EXPLORATION".equals(a.get("recordType"))).count(),"autonomousModelSearchesPassedInternalScreen",attempts.stream().filter(a->"UNVERIFIED_DATA_DERIVED_MODEL_CANDIDATE".equals(a.get("internalStatus"))).count(),"externallyReplicated",replicated,"failedAnalyses",failedRuns,"datasetsRejectedOrDownloadFailed",downloadFailures.size()));summary.put("status",attempts.isEmpty()&&imports.isEmpty()?found.isEmpty()?"NO_OPEN_RECORDS_FOUND":"NO_NUMERIC_CSV_IMPORTED":"AUTOMATED_SCREENING_COMPLETE_NOT_A_DISCOVERY");summary.put("limitations",List.of("Sumber awal hanya Zenodo dan paling banyak tiga CSV per siklus.","Impor mensyaratkan CSV numerik; kelolosan format tidak memverifikasi mutu ilmiah.","Validasi silang internal bukan replikasi independen.","Kecocokan pola bukan hukum fisika baru; turunan persamaan hanya manipulasi aljabar dari registri; desain mesin belum dihasilkan atau tervalidasi."));records.add(summary);return List.copyOf(records);
 }
 static List<Map<String,Object>> discoverImportedOnly(DataRepository repository,List<Map<String,Object>> imports){List<DataRepository.Dataset> selected=new ArrayList<>();for(Map<String,Object> imported:imports){Map<String,Object> dm=Json.map(imported.get("dataset"));selected.add(repository.get(Objects.toString(dm.get("id"),"")));}return selected.isEmpty()?List.of():DeterministicResearchEngine.discoverAll(selected);}
 private static Map<String,String> dimensionTokens(String source){Map<String,String> out=new LinkedHashMap<>();for(String pair:source.split(",")){String[] p=pair.trim().split(":",2);if(p.length==2)out.put(p[0].trim(),p[1].trim());}return out;}
 private static List<Map<String,Object>> deriveEquations(List<EquationRegistry.Equation> equations){List<Map<String,Object>> out=new ArrayList<>();for(int i=0;i<equations.size()&&out.size()<100;i++)for(int j=i+1;j<equations.size()&&out.size()<100;j++){var a=equations.get(i);var b=equations.get(j);Map<String,Dimensions.D> da,db;Map<String,String> rawA=dimensionTokens(a.variables()),rawB=dimensionTokens(b.variables());try{da=EquationRegistry.dimensions(a.variables());db=EquationRegistry.dimensions(b.variables());}catch(Exception ex){continue;}for(String shared:da.keySet())if(db.containsKey(shared)){Map<String,Dimensions.D> merged=new LinkedHashMap<>(da);boolean conflict=false;for(var e:db.entrySet()){Dimensions.D prior=merged.putIfAbsent(e.getKey(),e.getValue());if(prior!=null&&!prior.same(e.getValue())){conflict=true;break;}}if(conflict)continue;StringJoiner vars=new StringJoiner(",");merged.forEach((k,v)->vars.add(k+":"+rawA.getOrDefault(k,rawB.get(k))));try{Discovery.Combined c=Discovery.combine(a,b,shared,vars.toString(),"");Map<String,Object> item=new LinkedHashMap<>();item.put("status","ALGEBRAIC_DERIVATION_ONLY");item.put("equation",c.expression());item.put("sharedVariable",shared);item.put("dimensions",c.dimensions());item.put("derivation",c.derivation());item.put("sourceEquationA",Map.of("name",a.name(),"source",a.source(),"url",a.url(),"status",a.status()));item.put("sourceEquationB",Map.of("name",b.name(),"source",b.source(),"url",b.url(),"status",b.status()));out.add(item);if(out.size()>=100)break;}catch(Exception ignored){}}}return List.copyOf(out);}
 private static Map<String,Object> failure(String q,String status,String reason){Map<String,Object> m=new LinkedHashMap<>();m.put("id",UUID.randomUUID().toString());m.put("date",Instant.now().toString());m.put("recordType","AUTOMATED_RESEARCH_CYCLE");m.put("category","research");m.put("title","Siklus riset gagal: "+q);m.put("model","Open-data search → numeric CSV validation → model exploration");m.put("inputs",Map.of("query",q));m.put("result",Map.of("status",status,"reason",Objects.toString(reason,"unknown error")));m.put("status",status);m.put("sources",List.of());m.put("limitations",List.of("Siklus ini belum menghasilkan analisis data."));return m;}
}
